/**
 * RecruitDirect — contact double-check ("Contact check").
 *
 * Once a month, for every school and every sport (football, men's and women's basketball, baseball,
 * women's volleyball, softball), it reads every official place the school publishes its staff:
 *   1. the sport's coaches page (and the other common addresses for it when that one fails),
 *   2. the athletic department's staff directory (found once per site and remembered in "Staff Directories"),
 *   3. each coach's own bio page (only for coaches still missing something or not yet confirmed).
 * Emails hidden from robots (Cloudflare "email protection", entity-encoded mailto links, name [at] school [dot] edu)
 * are decoded first, so they are read like any other email.
 *
 * Then every coach's email, phone and X handle is cross-checked against what those pages say:
 *   - confirmed on an official page  -> kept, marked "verified", with the pages that confirm it
 *   - the pages list a different one -> replaced and recorded in Coach Changes as a contact change
 *   - missing                        -> filled from the pages
 *   - not found anywhere             -> kept, marked "unconfirmed" so the app can warn before sending
 * Emails must also pass: a real address, not a shared inbox (info@, athletics@, tickets@ ...), and a mail
 * domain that accepts email (MX record, checked through Google's public DNS). Nothing is ever deleted.
 *
 * One visit to a school's site checks all six sports there. A daily fetch cap keeps it well under
 * Apps Script's UrlFetch quota, so the existing staff scans keep running.
 *
 * Setup (once, in the script editor): run verifyInstall(). Status: verifyStatus(). One school: verifySchool('Baylor University').
 */
var VF_SPORTS_ = ['fb', 'mbb', 'wbb', 'base', 'vb', 'sb'];
var VF_COLS_ = ['Contact check', 'Verified on', 'Contact sources', 'Verify note'];
var VF_LOG_HEAD_ = ['When', 'School', 'Sports', 'Pages read', 'Coaches', 'Verified', 'Updated', 'Filled', 'Unconfirmed', 'Note'];
var VF_DIR_HEAD_ = ['Site', 'Directory page', 'Found', 'Last read', 'Result'];
var VF_DAILY_MAX_ = 6000;        /* fetches per day for this job; the whole project's limit is 20,000 */
var VF_BIOS_PER_SCHOOL_ = 30;    /* bio pages read per school visit (all sports together) */
var VF_RUN_MS_ = 210000;         /* work time per trigger run; saving takes the rest */
var VF_UA_ = { 'Accept': 'text/html', 'User-Agent': 'Mozilla/5.0 (compatible; RecruitDirect/1.0; +https://astew3.github.io/coaches-intel/legal/coaches.html)' };
var VF_DIR_PATHS_ = ['/staff-directory', '/staff.aspx', '/information/directory/index', '/information/staff_directory/index', '/staff', '/directory', '/athletics/staff-directory', '/about/staff-directory'];
var VF_GENERIC_ = /^(info|athletics?|tickets?|sports?|media|compliance|webmaster|web|admin|office|football|f?ball|basketball|mbb|wbb|baseball|softball|volleyball|recruit(ing)?|camps?|sid|sports?info|communications|marketing|noreply|no-reply|donotreply|do-not-reply|contact|hello|support|help|events?|development|giving|foundation|questionnaire|prospects?)[0-9._-]*@/i;
var VF_SRC_NAME_ = { s: 'staff page', d: 'directory', b: 'bio', o: 'office line' };
var VF_STATUS_CODE_ = { 'verified': 'v', 'updated': 'u', 'partly verified': 'p', 'unconfirmed': 'n', 'no contact': 'x' };

/* ---------- reading pages ---------- */
function vfCf_(hex) { var k = parseInt(hex.substr(0, 2), 16), s = ''; for (var i = 2; i + 1 < hex.length; i += 2) s += String.fromCharCode(parseInt(hex.substr(i, 2), 16) ^ k); return s; }
function vfEnt_(s) { return String(s).replace(/&#x([0-9a-f]+);?/gi, function (a, h) { return String.fromCharCode(parseInt(h, 16)); }).replace(/&#(\d+);?/g, function (a, d) { return String.fromCharCode(+d); }); }
/* Turns the common ways sites hide emails back into plain mailto links. Safe to run on any page. */
function deob_(html) {
  return String(html || '')
    .replace(/<(a|span)\b[^>]*data-cfemail=["']([0-9a-f]{4,})["'][^>]*>[\s\S]*?<\/\1>/gi, function (m, t, h) { var e = vfCf_(h); return '<a href="mailto:' + e + '">' + e + '</a>'; })
    .replace(/href=["'][^"']*\/cdn-cgi\/l\/email-protection#([0-9a-f]{4,})["']/gi, function (m, h) { return 'href="mailto:' + vfCf_(h) + '"'; })
    .replace(/href=["']((?:&#x?[0-9a-f]+;?){4,}[^"']*)["']/gi, function (m, u) { var d = vfEnt_(u); return /^mailto:/i.test(d) ? 'href="' + d + '"' : m; })
    .replace(/(^|[\s>(])((?:&#x?[0-9a-f]+;?){5,})(?=[\s<)])/gi, function (m, a, u) { var d = vfEnt_(u); return /^[^\s@<>]+@[^\s@<>]+\.[a-z]{2,}$/i.test(d) ? a + d : m; })
    .replace(/\b([A-Za-z0-9._%+-]+)\s*(?:\[|\(|\{)\s*at\s*(?:\]|\)|\})\s*([A-Za-z0-9-]+(?:\s*(?:\[|\(|\{)\s*dot\s*(?:\]|\)|\})\s*[A-Za-z0-9-]+)+)/gi,
      function (m, u, d) { return u + '@' + d.replace(/\s*(?:\[|\(|\{)\s*dot\s*(?:\]|\)|\})\s*/gi, '.'); });
}
function vfOrigin_(u) { var m = String(u || '').match(/^(https?:\/\/[^\/?#]+)/i); return m ? m[1].replace(/^http:/i, 'https:').toLowerCase() : ''; }
function vfAbs_(u, base) {
  u = String(u || '').trim().replace(/&amp;/g, '&'); if (!u || /^(mailto|tel|javascript|#)/i.test(u)) return '';
  if (/^https?:\/\//i.test(u)) return u;
  if (/^\/\//.test(u)) return 'https:' + u;
  var root = vfOrigin_(base); if (!root) return '';
  if (/^\//.test(u)) return root + u;
  var dir = String(base).replace(/[?#].*$/, '').replace(/\/[^\/]*$/, '/');
  return dir + u;
}
/* every person a page lists, with no sport filter: names are matched only to coaches already at this school */
function vfPeople_(html) {
  var h = stripHeavy_(html), out = [];
  try { out = parseTables_(h).concat(parseCards_(h)); } catch (e) {}
  return out.map(function (o) { o.n = cleanName_(o.n); o.k = normName_(o.n); if (o.e) o.e = vfEmail_(o.e); return o; }).filter(function (o) { return o.k; });
}
function vfEmail_(e) { e = String(e || '').trim().toLowerCase().replace(/^mailto:/, '').split('?')[0]; try { e = decodeURIComponent(e); } catch (x) {} return /^[a-z0-9._%+'-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(e) ? e : ''; }
function vfPhone_(p) { var m = String(p || '').replace(/^\+?1[\s.\-]?/, '').match(/^\(?(\d{3})\)?[\s.\-]{0,2}(\d{3})[\s.\-]?(\d{4})$/); return m && /^[2-9]/.test(m[1]) && /^[2-9]/.test(m[2]) ? m[1] + '-' + m[2] + '-' + m[3] : ''; }
function vfX_(x) { x = String(x || '').trim().replace(/^https?:\/\/(www\.)?(twitter|x)\.com\//i, '').replace(/^@/, '').replace(/[\/?#].*$/, ''); return /^[A-Za-z0-9_]{2,15}$/.test(x) ? '@' + x : ''; }
function vfMain_(html) { return deob_(stripHeavy_(html)).replace(/<(nav|header|footer)\b[\s\S]*?<\/\1>/gi, ' ').replace(/<aside\b[\s\S]*?<\/aside>/gi, ' '); }
function vfEmails_(h) {
  var out = {}, m, re = /mailto:([^"'?\s>]+@[^"'?\s>]+)/gi;
  while ((m = re.exec(h))) { var e = vfEmail_(m[1]); if (e) out[e] = 1; }
  var t = cleanText_(h), re2 = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;
  while ((m = re2.exec(t))) { var e2 = vfEmail_(m[0]); if (e2) out[e2] = 1; }
  return Object.keys(out);
}
/* links to each coach's bio: name key -> absolute url. Works for SIDEARM, PrestoSports, WMT and plain sites. */
function vfBioLinks_(html, base) {
  var out = {}, re = /<a\b[^>]*href=["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi, m;
  var h = stripHeavy_(html);
  while ((m = re.exec(h))) {
    var u = vfAbs_(m[1], base); if (!u || /\.(jpe?g|png|gif|webp|pdf|ics)(\?|$)/i.test(u)) continue;
    if (!/\/(coaches?|staff|bios?|staff-directory|roster\/coaches|directory)\b|[?&](rp_id|staff_id|id)=/i.test(u)) continue;
    var txt = cleanText_(m[2]), k = looksLikeName_(txt) ? normName_(cleanName_(txt)) : '';
    if (!k) {
      var sm = u.replace(/[?#].*$/, '').match(/\/(coaches?|staff(?:-directory)?|bios?)\/(?:[a-z0-9-]+\/)*?([a-z]+(?:[-_][a-z'.]+){1,3})(?:\/\d+)?\/?$/i);
      if (sm) k = normName_(sm[2].replace(/[_-]/g, ' '));
    }
    if (k && k.split(' ').length >= 2 && !out[k]) out[k] = u;
  }
  return out;
}
function vfFindBio_(bios, k) {
  if (bios[k]) return bios[k];
  var sk = shortKey_(k), hit = '';
  Object.keys(bios).some(function (b) { if (shortKey_(b) === sk) { hit = bios[b]; return true; } return false; });
  return hit;
}
function vfBioRead_(html) {
  var main = vfMain_(html), xm = cfX_(main), foot = (String(html || '').match(/<footer\b[\s\S]*$/i) || [''])[0];
  return { e: vfEmails_(main), p: Object.keys(cfPhones_(main)), x: Object.keys(xm).map(function (k) { return '@' + xm[k]; }), footX: cfX_(foot) };
}

/* ---------- quota-aware fetching ---------- */
function vfQuotaLeft_() { var p = PropertiesService.getScriptProperties(), k = 'VF_Q_' + day_(); return VF_DAILY_MAX_ - Number(p.getProperty(k) || 0); }
function vfCount_(n) { var p = PropertiesService.getScriptProperties(), k = 'VF_Q_' + day_(); p.setProperty(k, String(Number(p.getProperty(k) || 0) + n)); }
function vfFetch_(urls) {
  urls = urls.filter(Boolean); if (!urls.length) return [];
  vfCount_(urls.length);
  var reqs = urls.map(function (u) { return { url: u, muteHttpExceptions: true, followRedirects: true, validateHttpsCertificates: false, headers: VF_UA_ }; });
  var res; try { res = UrlFetchApp.fetchAll(reqs); } catch (e) { res = urls.map(function (u, i) { try { return UrlFetchApp.fetch(u, reqs[i]); } catch (x) { return null; } }); }
  return res.map(function (r, i) { var code = 0, html = ''; try { code = r ? r.getResponseCode() : 0; if (code === 200) html = r.getContentText(); } catch (e) {} return { url: urls[i], code: code, html: html }; });
}
/* does this email domain accept mail? Google public DNS, cached for a week */
var VF_MX_ = {};
function vfMxOk_(domain) {
  domain = String(domain || '').toLowerCase(); if (!domain) return false;
  if (VF_MX_[domain] !== undefined) return VF_MX_[domain];
  var c = CacheService.getScriptCache(), hit = c.get('MX_' + domain);
  if (hit) return (VF_MX_[domain] = hit === '1');
  var ok = true;   /* if DNS can't be reached, don't punish the email */
  try {
    vfCount_(1);
    var r = UrlFetchApp.fetch('https://dns.google/resolve?name=' + encodeURIComponent(domain) + '&type=MX', { muteHttpExceptions: true });
    if (r.getResponseCode() === 200) { var j = JSON.parse(r.getContentText()); ok = j.Status === 0 && ((j.Answer || []).length > 0 || vfHasA_(domain)); }
  } catch (e) {}
  try { c.put('MX_' + domain, ok ? '1' : '0', 21600); } catch (e) {}
  return (VF_MX_[domain] = ok);
}
function vfHasA_(domain) {   /* no MX but an A record still receives mail */
  try { vfCount_(1); var r = UrlFetchApp.fetch('https://dns.google/resolve?name=' + encodeURIComponent(domain) + '&type=A', { muteHttpExceptions: true }); var j = JSON.parse(r.getContentText()); return j.Status === 0 && (j.Answer || []).length > 0; } catch (e) { return true; }
}

/* ---------- deciding (pure: no services, tested locally) ---------- */
function vfNameScore_(email, name) {
  var local = String(email || '').split('@')[0].toLowerCase().replace(/[^a-z]/g, '');
  var w = normName_(name).split(' ').filter(function (x) { return x.length > 1; }); if (!local || !w.length) return 0;
  var first = w[0], last = w[w.length - 1].replace(/[^a-z]/g, ''), sc = 0;
  if (last.length >= 3 && local.indexOf(last) >= 0) sc += 2;
  if (first.length >= 3 && local.indexOf(first) >= 0) sc += 1;
  else if (last.length >= 3 && (local.indexOf(first.charAt(0) + last) === 0 || local.indexOf(last + first.charAt(0)) === 0)) sc += 1;
  return sc;
}
function vfEmailUsable_(e, mxOk) { return !!e && !VF_GENERIC_.test(e) && (!mxOk || mxOk(e.split('@')[1])); }
/* cur: {n, e, p, x}. ev: {e:{value:{s:1,d:1,b:1}}, p:{...}, x:{...}}. opts.mxOk(domain), opts.noEmails (school publishes no emails).
   Returns the new values, what changed, a status and a short note. */
function vfDecide_(cur, ev, opts) {
  opts = opts || {};
  var out = { e: vfEmail_(cur.e) || String(cur.e || '').trim().toLowerCase(), p: vfPhone_(cur.p) || String(cur.p || '').trim(), x: cur.x ? vfX_(cur.x) || cur.x : '',
    changed: {}, ok: {}, src: {}, notes: [] };
  function srcs(o) { return Object.keys(o || {}).filter(function (k) { return VF_SRC_NAME_[k]; }); }
  function weight(v, o, name) { var s = srcs(o), w = s.length * 10; if (o.b) w += 3; if (o.d) w += 2; if (o.s) w += 1; if (name) w += vfNameScore_(v, name) * 4 + (/\.edu$/.test(v) ? 2 : 0); return w; }
  /* email */
  var E = ev.e || {}, curE = out.e, mx = opts.mxOk;
  var cands = Object.keys(E).filter(function (v) { return vfEmailUsable_(v, mx); });
  if (curE && E[curE] && vfEmailUsable_(curE, mx)) { out.ok.e = 1; out.src.e = srcs(E[curE]); }
  else if (cands.length) {
    cands.sort(function (a, b) { return weight(b, E[b], cur.n) - weight(a, E[a], cur.n); });
    var best = cands[0], bs = srcs(E[best]);
    var tie = cands.length > 1 && weight(cands[1], E[cands[1]], cur.n) === weight(best, E[best], cur.n) && vfNameScore_(best, cur.n) === 0;
    if (tie) out.notes.push('Pages list more than one email for this coach (' + cands.slice(0, 3).join(', ') + ')');
    else if (!curE) { out.e = best; out.changed.e = ['', best]; out.ok.e = 1; out.src.e = bs; }
    else {
      var curBad = !vfEmail_(curE) || VF_GENERIC_.test(curE) || (mx && !mx(curE.split('@')[1]));
      var nb = vfNameScore_(best, cur.n), nc = vfNameScore_(curE, cur.n), strong = bs.length >= 2 || E[best].s || E[best].d;
      var better = curBad || (strong && nb >= nc) || (nb > nc && nb >= 2);
      if (better) { out.changed.e = [curE, best]; out.e = best; out.ok.e = 1; out.src.e = bs; }
      else out.notes.push('School pages list ' + best + ' (' + bs.map(function (k) { return VF_SRC_NAME_[k]; }).join(', ') + ')');
    }
  } else if (curE) {
    if (!vfEmail_(curE)) out.notes.push('Saved email is not a valid address');
    else if (mx && !mx(curE.split('@')[1])) out.notes.push('Email domain ' + curE.split('@')[1] + ' does not accept mail');
    else if (VF_GENERIC_.test(curE)) out.notes.push('Saved email is a shared inbox');
    else if (!opts.noEmails) out.notes.push('Email not found on the school\'s pages');
  }
  /* phone: office lines (shared by several coaches) confirm a saved number but never replace one */
  var P = ev.p || {}, curP = vfPhone_(out.p);
  var pc = Object.keys(P).filter(function (v) { return srcs(P[v]).some(function (k) { return k !== 'o'; }); });
  var direct = pc.filter(function (v) { return P[v].s || P[v].d; });
  if (curP && P[curP] && srcs(P[curP]).join('') === 'o' && direct.length === 1 && direct[0] !== curP) {   /* saved number is the office line; the school lists a direct line */
    out.changed.p = [curP, direct[0]]; out.p = direct[0]; out.ok.p = 1; out.src.p = srcs(P[direct[0]]);
  }
  else if (curP && P[curP]) { out.ok.p = 1; out.src.p = srcs(P[curP]); out.p = curP; }
  else if (pc.length === 1 && (!curP || P[pc[0]].s || P[pc[0]].d)) { out.changed.p = [String(cur.p || ''), pc[0]]; out.p = pc[0]; out.ok.p = 1; out.src.p = srcs(P[pc[0]]); }
  else if (pc.length > 1) {
    pc.sort(function (a, b) { return weight(b, P[b]) - weight(a, P[a]); });
    if (weight(pc[0], P[pc[0]]) > weight(pc[1], P[pc[1]]) && (!curP || P[pc[0]].s || P[pc[0]].d)) { out.changed.p = [String(cur.p || ''), pc[0]]; out.p = pc[0]; out.ok.p = 1; out.src.p = srcs(P[pc[0]]); }
  } else if (!curP) { var office = Object.keys(P); if (office.length === 1 && !cur.p) { out.p = office[0]; out.changed.p = ['', office[0]]; out.ok.p = 1; out.src.p = ['o']; } }
  if (out.changed.p && !out.changed.p[0]) out.changed.p[0] = '';
  /* X: filled when one handle is linked from the coach's own entry; never replaced (people add these by hand) */
  var X = ev.x || {}, xs = Object.keys(X), curX = out.x ? out.x.toLowerCase() : '';
  if (curX && xs.some(function (v) { return v.toLowerCase() === curX; })) { out.ok.x = 1; out.src.x = srcs(X[xs.filter(function (v) { return v.toLowerCase() === curX; })[0]]); }
  else if (!curX && xs.length === 1) { out.x = xs[0]; out.changed.x = ['', xs[0]]; out.ok.x = 1; out.src.x = srcs(X[xs[0]]); }
  /* status */
  var has = (out.e ? 1 : 0) + (out.p ? 1 : 0), conf = (out.e && out.ok.e ? 1 : 0) + (out.p && out.ok.p ? 1 : 0);
  var upd = !!(out.changed.e && out.changed.e[0]) || !!(out.changed.p && out.changed.p[0]);
  out.status = !has ? 'no contact' : upd ? 'updated' : conf === has ? 'verified' : conf ? 'partly verified' : 'unconfirmed';
  if (out.status === 'unconfirmed' && opts.noEmails && !out.p && out.e) out.status = 'partly verified';
  var parts = [];
  ['e', 'p', 'x'].forEach(function (f) { if (out.src[f] && out.src[f].length) parts.push({ e: 'email', p: 'phone', x: 'X' }[f] + ': ' + out.src[f].map(function (k) { return VF_SRC_NAME_[k]; }).join(', ')); });
  out.sources = parts.join(' · ');
