}

/* ---------- sheets ---------- */
function vfEnsureCols_() {
  var cs = coachSheet_(), head = cs.head, add = VF_COLS_.filter(function (h) { return head.indexOf(h) < 0; });
  if (add.length) cs.sh.getRange(1, head.length + 1, 1, add.length).setValues([add]).setFontWeight('bold').setBackground('#0B0C0E').setFontColor('#C6F432');
}
function vfDirs_() {
  var sh = plainSheet_('Staff Directories', VF_DIR_HEAD_), last = sh.getLastRow(), v = last > 1 ? sh.getRange(2, 1, last - 1, VF_DIR_HEAD_.length).getValues() : [], map = {};
  v.forEach(function (r, i) { map[String(r[0])] = { row: i + 2, url: String(r[1] || ''), found: r[2], read: r[3], res: String(r[4] || '') }; });
