  if (D.add.length) D.sh.getRange(D.sh.getLastRow() + 1, 1, D.add.length, VF_DIR_HEAD_.length).setValues(D.add.map(function (k) { var o = D.map[k]; return [k, o.url, o.found, o.read, o.res]; }));
  D.add = []; D.dirty = {};
}
/* every school in any sport, with that sport's school record */
function vfSchools_() {
  var by = {};
  VF_SPORTS_.forEach(function (sp) { withSport_(sp, function () {
    var list = []; try { list = scanSchools_(); } catch (e) {}
    list.forEach(function (s) { var o = by[s.n] || (by[s.n] = { n: s.n, w: '', sd: '', sp: {} }); o.sp[sp] = s; if (!o.w && s.w) o.w = s.w; if (!o.sd && s.sd) o.sd = s.sd; });
  }); });
  return Object.keys(by).sort().map(function (k) { return by[k]; });
}
function vfContexts_() { var c = {}; VF_SPORTS_.forEach(function (sp) { withSport_(sp, function () { vfEnsureCols_(); c[sp] = scanContext_(SPORT_.log); }); }); return c; }
function vfSaveContexts_(ctxs) {
  VF_SPORTS_.forEach(function (sp) { if (ctxs[sp]) withSport_(sp, function () { saveContext_(ctxs[sp]); }); });
  try { clearSeedCache_(); ['base', 'vb', 'sb'].forEach(function (sp) { xsClearCache_(sp); }); } catch (e) {}
}

/* ---------- one school, every sport ---------- */
function vfSchool_(S, ctxs, D, opts) {
  opts = opts || {};
  var st = { pages: 0, coaches: 0, v: 0, u: 0, f: 0, n: 0, sports: [], note: [] };
  /* coaches at this school, per sport */
  var rows = {};
  VF_SPORTS_.forEach(function (sp) {
    var ctx = ctxs[sp]; if (!ctx || !S.sp[sp]) return;
    var r = (ctx.bySchool[S.n] || []).filter(function (i) { return String(rowGet_(ctx, i, 'Status')) !== 'departed'; });
    if (opts.sport && opts.sport !== sp) r = [];
    if (r.length) { rows[sp] = r; st.sports.push(sp); }
  });
  if (!st.sports.length) { st.note.push('no coaches on file'); return st; }
  var site = vfOrigin_(S.w) || vfOrigin_(S.sp[st.sports[0]].cp);
  /* 1) staff pages + the department directory, in one round */
  var dir = D.map[site] || null, month = month_(), probe = [];
  var dirUrl = dir && dir.url && dir.url !== 'none' ? dir.url : '';
  if (!dirUrl && site && (!dir || !dir.url || daysBetween_(cellDay_(dir.read), day_()) > 180)) {
    probe = (S.sd ? [S.sd] : []).concat(VF_DIR_PATHS_.map(function (p) { return site + p; }));
    probe = probe.filter(function (u, i) { return probe.indexOf(u) === i; });
  }
  var want = st.sports.map(function (sp) { return S.sp[sp].cp; }).concat(dirUrl ? [dirUrl] : probe);
  var got = vfFetch_(want); st.pages += got.filter(function (g) { return g.html; }).length;
  var staff = {}; st.sports.forEach(function (sp, i) { staff[sp] = got[i]; });
  var dirHtml = '', dirFrom = '';
  got.slice(st.sports.length).some(function (g) {
    if (!g.html || !/coach/i.test(g.html)) return false;
    if (vfPeople_(g.html).length < 5) return false;
    dirHtml = g.html; dirFrom = g.url; return true;
  });
